"""Assembles evaluation_report.md from the JSON files in results/. Only REAL result files are used; if the
generation evaluation has not been run with a real LLM the report says so instead of showing numbers."""
import json

from common import RESULTS

OUT = RESULTS.parent / "evaluation_report.md"
md = ["# ScholarMind AI — Evaluation Report", "",
      "Generated by `evaluation/build_report.py` from `evaluation/results/*.json`. Nothing in this file is typed by hand; "
      "every number comes from a script run, and sections say when a step has **not** been run.", "",
      "Corpus: 3 original sample documents (`sample_data/`), 16 hand-written questions (`evaluation/evaluation_dataset.json`): "
      "14 answerable (each with a verified expected page/section) and 2 out of scope.", ""]
rp = RESULTS / "retrieval_results.json"
if rp.exists():
    r = json.loads(rp.read_text())
    s = r["summary"]
    md += ["## 1. Retrieval evaluation (automatic)", "",
           f"- Run: {r['timestamp']}  |  Embedder: **{r['embedder']}** ({'semantic model' if r['semantic_embedder'] else '**lexical fallback — NOT semantic**'})",
           f"- Chunking: {r['chunk_size']} chars, overlap {r['chunk_overlap']}  |  Relevance threshold (MIN_SCORE): {r['min_score_threshold']}", "",
           "| Metric | K=1 | K=3 | K=5 |", "|---|---|---|---|",
           f"| Precision@K | {s['precision@1']} | {s['precision@3']} | {s['precision@5']} |",
           f"| Recall@K (hit rate) | {s['recall@1']} | {s['recall@3']} | {s['recall@5']} |", "",
           f"**MRR = {s['MRR']}**  |  False-refusal rate = {s['false_refusal_rate']} (in-scope questions scoring below the threshold: {', '.join(r['false_refusal_ids']) or 'none'})  |  "
           f"Out-of-scope correctly below threshold: {s['out_of_scope_correctly_refused']}", "",
           "| ID | Question | Expected | First relevant rank | Top score | Top-3 retrieved |", "|---|---|---|---|---|---|"]
    for q in r["per_question"]:
        md.append(f"| {q['id']} | {q['question']} | {q['expected']} | {q['first_relevant_rank'] or 'not in top 10'} | {q['top_score']:.2f} | {'; '.join(q['retrieved'][:3])} |")
    md += ["", "Out-of-scope questions:", ""]
    md += [f"- {o['id']} “{o['question']}” — best score {o['top_score']:.2f} → {'**wrongly above**' if o['passes_threshold'] else 'correctly below'} threshold" for o in r["out_of_scope"]]
    if not r["semantic_embedder"]:
        md += ["", "> **Limitation:** this run used the lexical fallback embedder because the semantic model could not be downloaded in the build "
               "environment. It matches words, not meaning, so these scores are a *lower bound*. Re-run `python evaluation/evaluate_retrieval.py` "
               "on a machine where `all-MiniLM-L6-v2` loads and report those numbers instead. The false refusals above show that the default "
               "`MIN_SCORE=0.12` is too strict for the fallback embedder; it has not been tuned for MiniLM."]
else:
    md += ["## 1. Retrieval evaluation", "", "**Not run.** Execute `python evaluation/evaluate_retrieval.py`.", ""]
gp = RESULTS / "generation_results.json"
md += ["", "## 2. Generation evaluation", ""]
if gp.exists():
    g = json.loads(gp.read_text())
    md += [f"- Run: {g['timestamp']}  |  LLM: **{g['llm']}**  |  Embedder: {g['embedder']}", "", "| Metric | Mean |", "|---|---|"]
    md += [f"| {k} | {v} |" for k, v in g["summary"].items()]
    md += ["", "`faithfulness_proxy` is a lexical overlap measure, not a semantic faithfulness judgement. Human-review columns below are **blank until a person fills them in**.", "",
           "| ID | Question | Status | Tool | Answer (truncated) | Retrieved | Human: faithful? | Human: complete? | Observed limitation |", "|---|---|---|---|---|---|---|---|---|"]
    for q in g["per_question"]:
        ans = q["answer"].replace("\n", " ").replace("|", "/")[:220]
        md.append(f"| {q['id']} | {q['question']} | {q['status']} | {q.get('tool')} | {ans} | {'; '.join(q['retrieved'][:3])} | {q['human_faithful']} | {q['human_complete']} | {q['human_notes']} |")
else:
    md += ["**Not run in the build environment.** No LLM was reachable there (no Ollama, and the Hugging Face / Ollama hosts were blocked), "
           "so no generation scores exist and none are invented. To produce them:", "",
           "```powershell", "ollama pull qwen2.5:3b-instruct", "python evaluation/evaluate_generation.py", "python evaluation/build_report.py", "```", "",
           "The script measures answer status, expected-source citation, citation validity, keyword coverage, context utilisation, a lexical "
           "faithfulness proxy and out-of-scope refusal, and leaves human-review columns for you to fill in."]
OUT.write_text("\n".join(md) + "\n", encoding="utf-8")
print("wrote", OUT)
